const labels = [
 'sample_2022-03-25_control_replicate_1 compared with sample_2022-04-13_control_replicate_1',
 'sample_2022-03-25_control_replicate_2 compared with sample_2022-04-13_control_replicate_2'
];
const values = labels.flatMap((x,i) => labels.map((y,j) => ({x,y,z:i===j?1:.76})));
chart().createCanvas({width:130,height:130,margin:50})
 .createData({values})
 .createHeatmap({x:'x',y:'y',color:{field:'z',fieldType:'quantitative'},
   guides:{axes:{
     x:{title:false,ticksAndLabels:{labels:{rotation:{value:-90,unit:'degrees'},fontSize:10}}},
     y:{title:false,ticksAndLabels:{labels:{fontSize:10}}}
   },legend:false}
