Save as `repro.mjs` in a project with `npm install ggaction@0.0.17`, then run `node repro.mjs`. This uses synthetic data and does not need Vega-Lite or a browser.

```js
import { chart } from 'ggaction';
const rows = [
  { weekday: 'Mon', rank: 0, group: 'A', total: 10 },
  { weekday: 'Tue', rank: 1, group: 'A', total: 20 },
  { weekday: 'Mon', rank: 0, group: 'B', total: 5 },
  { weekday: 'Tue', rank: 1, group: 'B', total: 8 }
];
const base = () => chart().createCanvas().createData({ values: rows });
const cases = {
  categoricalFacade: () => base().createAreaPlot({
