    y: 'total', groupBy: 'group', layout: 'stack', guides: false
  }),
  categoricalLowLevel: () => base().createAreaMark().encodeX({
    field: 'weekday', fieldType: 'ordinal',
    scale: { type: 'point', domain: ['Mon', 'Tue'] }
  }),
  numericControl: () => base().createAreaPlot({
    x: 'rank', y: 'total', groupBy: 'group', layout: 'stack', guides: false
  }),
  numericRankLabelMap: () => base().createAreaPlot({
    x: 'rank', y: 'total', groupBy: 'group', layout: 'stack', guides: false
  }).createXAxis({
